-- PT101-S2-Q15. Batch 08.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch08$PT101-S2-Q15$batch08$ AND q.stimulus=$batch08$The authors of a recent article examined warnings of an impending wave of extinctions of animal species within the next 100 years. These authors say that no evidence exists to support the idea that the rate of extinction of animal species is now accelerating. They are wrong, however. Consider only the data on fishes: 40 species and subspecies of North American fishes have vanished in the twentieth century, 13 between 1900 and 1950, and 27 since 1950.$batch08$ AND q.prompt=$batch08$Which one of the following is the main point of the argument?$batch08$ AND q.correct_choice=$batch08$A$batch08$) THEN RAISE EXCEPTION 'Question changed: PT101-S2-Q15'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch08$PT101-S2-Q15$batch08$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT101-S2-Q15'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch08$PT101-S2-Q15$batch08$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch08$Conclusion$batch08$, $batch08$The authors are wrong: there *is* evidence that the extinction rate is accelerating.$batch08$), (1, $batch08$Evidence$batch08$, $batch08$40 North American fish species and subspecies vanished in the twentieth century, 13 in the first half and 27 since 1950.$batch08$), (2, $batch08$Evaluate$batch08$, $batch08$"They are wrong, however" is the author's verdict on the article's claim that no evidence exists. Everything after "Consider" is evidence for that verdict. So the conclusion is the denial of the authors' claim.$batch08$), (3, $batch08$Goal$batch08$, $batch08$There is evidence that extinctions are accelerating.$batch08$)) v(position,label,body) WHERE q.qid=$batch08$PT101-S2-Q15$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch08$A$batch08$, $batch08$The authors said no evidence exists; the author says they're wrong. A states the result.$batch08$), ($batch08$B$batch08$, $batch08$The author argues the evidence does show a trend.$batch08$), ($batch08$C$batch08$, $batch08$The fish data are offered as one example, not as a match for all species.$batch08$), ($batch08$D$batch08$, $batch08$This is the fish data, the support, not the point.$batch08$), ($batch08$E$batch08$, $batch08$The argument is about the rate so far, not which fish are in danger now.$batch08$)) v(letter,body) WHERE q.qid=$batch08$PT101-S2-Q15$batch08$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
COMMIT;
